-- Venue Live Guest "Wedding Observatory". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara observatory), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'observatory', 'Wedding Observatory', 'observatory', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 145, 'center 38%',
  $t${"name":"Observatory","orn":"diamond","ui":{"ivory":"#F4F1F8","white":"#FFFFFF","soft":"#DEDDEE","soft2":"#D7A93B","accent":"#26305F","deep":"#161B3A","ink":"#161B3A","mute":"#6E6F95","line":"#D6D6E8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#EDEAF4","ink":"#161B3A","accent":"#26305F","gold":"#D7A93B","leaf":"#DEDDEE","hbg":"rgba(244,241,248,.94)","hline":"#D7A93B","motif":"diamond"},"hud":{"bg":"rgba(22,27,58,.9)","acc":"#F2D27A","on":"#161B3A"},"scr":{"wine":"#161B3A","veil":"244,241,248"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'observatory');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/observatory/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/observatory/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/observatory/stall_snacks.webp","w":2.8},"stall_candy":{"url":"/assets/live-decor/observatory/stall_candy.webp","w":8.4,"x":-14.5,"z":4.5},"stall_drinks":{"url":"/assets/live-decor/observatory/stall_drinks.webp","w":10.0,"x":-9.4,"z":-11.5},"photobooth":{"url":"/assets/live-decor/observatory/photobooth.webp","w":6.8},"claw":{"url":"/assets/live-decor/observatory/claw.webp","w":8.4},"arch":{"url":"/assets/live-decor/observatory/arch.webp"},"fountain":{"url":"/assets/live-decor/observatory/fountain.webp","w":7.8,"x":9.3,"z":-15.5},"sign":{"url":"/assets/live-decor/observatory/sign.webp","w":1.9,"x":-5.6,"z":9},"easel":{"url":"/assets/live-decor/observatory/easel.webp","w":4.2,"x":5.2,"z":10.0},"table":{"url":"/assets/live-decor/observatory/table.webp","w":3.6,"x":-8.8,"z":3.6},"banner":{"url":"/assets/live-decor/observatory/banner.webp","w":1.5,"x":9.6,"z":8.8},"gifts":{"url":"/assets/live-decor/observatory/gifts.webp","w":2.0},"lamp":{"url":"/assets/live-decor/observatory/lamp.webp","w":1.4,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/observatory/rope.webp","w":1.5,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/observatory/planter.webp","w":1.4,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/observatory/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/observatory/av_host.webp","name":"Pengantin"},"av_l1":{"url":"/assets/live-decor/observatory/av_l1.webp","name":"Kak Jas Bintang"},"av_l2":{"url":"/assets/live-decor/observatory/av_l2.webp","name":"Kak Kacamata Bow Tie"},"av_l3":{"url":"/assets/live-decor/observatory/av_l3.webp","name":"Kak Baret Bintang"},"av_p1":{"url":"/assets/live-decor/observatory/av_p1.webp","name":"Kak Gaun Tulle"},"av_p2":{"url":"/assets/live-decor/observatory/av_p2.webp","name":"Kak Hijab Navy"},"av_p3":{"url":"/assets/live-decor/observatory/av_p3.webp","name":"Kak Gaun Tas"}}$d$::jsonb, background_url = '/assets/live-decor/observatory/painting.webp', active = true, updated_at = now() where key = 'observatory';
